#include <furi.h>
#include <gui/gui.h>
#include <input/input.h>
#include <stdio.h>
#include <stdlib.h>
typedef struct {int x,y,alive;} Enemy;
typedef struct {FuriMutex* lock; int x,y,dx,dy,stage,mode,score,weapon,ammo,mask,tick; bool held[4]; Enemy e[6];} Game;
static bool wall(int x,int y){return x<3||x>124||y<13||y>60||(((x>=39&&x<=42)||(x>=83&&x<=86))&& (y<29||y>42));}
static void reset(Game*g){g->x=12;g->y=35;g->dx=1;g->dy=0;g->ammo=8;g->weapon=0;g->tick=0;for(int i=0;i<6;i++){g->e[i]=(Enemy){55+(i%3)*28,19+(i/3)*34,1};}g->mode=1;}
static void draw(Canvas*c,void*p){Game*g=p;furi_mutex_acquire(g->lock,FuriWaitForever);canvas_clear(c);canvas_set_font(c,FontSecondary);
if(g->mode!=1){canvas_set_font(c,FontPrimary);canvas_draw_str(c,4,14,"HOTLINE MIAMI");canvas_set_font(c,FontSecondary);canvas_draw_str(c,4,29,g->mode==0?"OK: Start  Left/Right: Mask":g->mode==2?"Paused - OK: Resume":g->mode==3?"Wasted - OK: Retry":"Clear! OK: Next");canvas_draw_str(c,4,43,"Arrows: Move  OK: Attack");canvas_draw_str(c,4,56,"Hold OK: Weapon  Back: Menu");}
else{char s[64];snprintf(s,sizeof(s),"L%d %s %d  P:%d",g->stage,g->weapon?"GUN":"BAT",g->ammo,g->score);canvas_draw_str(c,2,9,s);canvas_draw_frame(c,1,11,126,52);for(int x=39;x<=83;x+=44){canvas_draw_box(c,x,13,4,16);canvas_draw_box(c,x,43,4,18);}canvas_draw_disc(c,g->x,g->y,3);canvas_draw_line(c,g->x,g->y,g->x+g->dx*6,g->y+g->dy*6);for(int i=0;i<6;i++){Enemy*e=&g->e[i];if(e->alive){canvas_draw_frame(c,e->x-3,e->y-3,7,7);canvas_draw_dot(c,e->x,e->y);}else{canvas_draw_line(c,e->x-2,e->y-2,e->x+2,e->y+2);canvas_draw_line(c,e->x+2,e->y-2,e->x-2,e->y+2);}}}furi_mutex_release(g->lock);}
static void input(InputEvent*e,void*p){furi_message_queue_put(p,e,0);}
static void attack(Game*g){if(g->weapon&&g->ammo<=0)return;if(g->weapon)g->ammo--;int best=-1,dist=999;for(int i=0;i<6;i++){Enemy*e=&g->e[i];int a=e->x-g->x,b=e->y-g->y,d=abs(a)+abs(b);if(!e->alive||d> (g->weapon?65:12))continue;if(g->weapon&&(a*g->dx+b*g->dy<=0||abs(a*g->dy-b*g->dx)>5))continue;bool blocked=false;for(int k=1;k<d;k++)if(wall(g->x+a*k/d,g->y+b*k/d))blocked=true;if(!blocked&&d<dist){best=i;dist=d;}}if(best>=0){g->e[best].alive=0;g->score+=100;}}
int32_t hotline_main(void*ctx){UNUSED(ctx);Game*g=calloc(1,sizeof(Game));g->lock=furi_mutex_alloc(FuriMutexTypeNormal);g->stage=1;FuriMessageQueue*q=furi_message_queue_alloc(16,sizeof(InputEvent));ViewPort*v=view_port_alloc();view_port_draw_callback_set(v,draw,g);view_port_input_callback_set(v,input,q);Gui*gui=furi_record_open(RECORD_GUI);gui_add_view_port(gui,v,GuiLayerFullscreen);bool run=true;while(run){InputEvent e;bool got=furi_message_queue_get(q,&e,33)==FuriStatusOk;furi_mutex_acquire(g->lock,FuriWaitForever);if(got){int k=e.key;if(k>=InputKeyUp&&k<=InputKeyRight){g->held[k]=e.type!=InputTypeRelease;if(e.type==InputTypeShort&&g->mode==0)g->mask^=1;}if(e.type==InputTypeShort&&k==InputKeyBack){if(g->mode==0)run=false;else if(g->mode==1)g->mode=2;else g->mode=0;}if(k==InputKeyOk){if(e.type==InputTypeLong&&g->mode==1)g->weapon^=1;if(e.type==InputTypeShort){if(g->mode==1)attack(g);else if(g->mode==2)g->mode=1;else{if(g->mode==4)g->stage++;reset(g);}}}}if(g->mode==1){int dx=g->held[InputKeyRight]-g->held[InputKeyLeft],dy=g->held[InputKeyDown]-g->held[InputKeyUp];if(dx||dy){g->dx=dx;g->dy=dy;if(!wall(g->x+dx,g->y))g->x+=dx;if(!wall(g->x,g->y+dy))g->y+=dy;}int alive=0;g->tick++;for(int i=0;i<6;i++){Enemy*a=&g->e[i];if(!a->alive)continue;alive++;int x=g->x-a->x,y=g->y-a->y;if(abs(x)+abs(y)<5)g->mode=3;if(g->tick%4==0&&abs(x)+abs(y)<38){int sx=(x>0)-(x<0),sy=(y>0)-(y<0);if(!wall(a->x+sx,a->y))a->x+=sx;if(!wall(a->x,a->y+sy))a->y+=sy;}}if(!alive)g->mode=4;}furi_mutex_release(g->lock);view_port_update(v);}gui_remove_view_port(gui,v);view_port_free(v);furi_record_close(RECORD_GUI);furi_message_queue_free(q);furi_mutex_free(g->lock);free(g);return 0;}
